    if activities[0] == 2 or activities[0] == 3:
        dp_sport[0] = 1
    else:
        dp_sport[0] = 0

    # Fill DP tables
    for i in range(1, n):
        if activities[i] == 0:
            dp_rest[i] = min(dp_rest[i-1] + 1, dp_contest[i-1], dp_sport[i-1])
        elif activities[i] == 1:
